// ИСТОЧНИКИ НОВОСТЕЙ
// Каждая строка — одна RSS-лента. Добавляйте адреса RSS нужных сайтов.
// Поиск по теме через Google Новости: https://news.google.com/rss/search?q=ЗАПРОС&hl=ru&gl=RU&ceid=RU:ru
// (пробелы в запросе заменяйте на +, кавычки — на %22)
const feeds = [
  { name: 'Google Новости: Читинская епархия', url: 'https://news.google.com/rss/search?q=%22%D0%A7%D0%B8%D1%82%D0%B8%D0%BD%D1%81%D0%BA%D0%B0%D1%8F+%D0%B5%D0%BF%D0%B0%D1%80%D1%85%D0%B8%D1%8F%22&hl=ru&gl=RU&ceid=RU:ru' },
  { name: 'Google Новости: православие Забайкалье', url: 'https://news.google.com/rss/search?q=%D0%BF%D1%80%D0%B0%D0%B2%D0%BE%D1%81%D0%BB%D0%B0%D0%B2%D0%B8%D0%B5+%D0%97%D0%B0%D0%B1%D0%B0%D0%B9%D0%BA%D0%B0%D0%BB%D1%8C%D0%B5&hl=ru&gl=RU&ceid=RU:ru' },
  // { name: 'Сайт епархии', url: 'https://АДРЕС-САЙТА/rss' },
];
return feeds.map(f => ({ json: f }));

// ОТБОР ПО ТЕМЕ
// KEYWORDS — части слов (в нижнем регистре), хотя бы одна должна встретиться
// в заголовке или аннотации. Пустой список = брать всё из лент
// (для лент Google Новости тема уже задана поисковым запросом).
const KEYWORDS = [];            // например: ['епархи', 'митрополи', 'храм', 'монголи']
const MAX_AGE_DAYS = 3;         // не старше стольких дней

const cutoff = Date.now() - MAX_AGE_DAYS * 24 * 3600 * 1000;
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.error || !j.link || !j.title) continue;          // лента не открылась или пустая запись
  const date = new Date(j.isoDate || j.pubDate || Date.now());
  if (date.getTime() < cutoff) continue;
  const hay = `${j.title} ${j.contentSnippet || ''}`.toLowerCase();
  if (KEYWORDS.length && !KEYWORDS.some(k => hay.includes(k))) continue;
  if (seen.has(j.link)) continue;
  seen.add(j.link);
  // В Google Новостях источник указан в конце заголовка после « - »
  const m = j.title.match(/^(.*)\s+-\s+([^-]+)$/);
  out.push({ json: {
    title: m ? m[1] : j.title,
    source: m ? m[2] : (j.creator || ''),
    link: j.link,
    date: date.toISOString(),
  }});
}
return out;

// СБОРКА ПОДБОРКИ В ОДНО СООБЩЕНИЕ
const MAX_ITEMS = 10;
const items = $input.all().map(i => i.json)
  .sort((a, b) => b.date.localeCompare(a.date))
  .slice(0, MAX_ITEMS);
if (!items.length) return [];

const fmt = d => new Date(d).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', timeZone: 'Asia/Chita' });
const lines = items.map((n, i) =>
  `${i + 1}. ${n.title}\n${[n.source, fmt(n.date)].filter(Boolean).join(' · ')}\n${n.link}`);

const text = `📰 Подборка новостей — ${fmt(new Date().toISOString())}\n\n` +
  lines.join('\n\n') +
  `\n\nЧтобы опубликовать новость на сайте, откройте её и пришлите боту ссылку на статью.`;
return [{ json: { text: text.slice(0, 4000) } }];
